<?php
defined( 'ABSPATH' ) || exit;

final class Matin_AI_Account {
	public static function init() : void { add_shortcode( 'matin_ai_account', [ __CLASS__, 'render' ] ); add_action( 'init', [ __CLASS__, 'maybe_create_page' ] ); add_action( 'wp_enqueue_scripts', [ __CLASS__, 'styles' ] ); }
	public static function maybe_create_page() : void {
		if ( get_option( 'matin_ai_account_page_created' ) ) { return; }
		$page = get_page_by_path( 'my-account' );
		if ( ! $page ) { $id = wp_insert_post( [ 'post_type' => 'page', 'post_status' => 'publish', 'post_title' => 'حساب کاربری من', 'post_name' => 'my-account', 'post_content' => '[matin_ai_account]' ] ); if ( ! is_wp_error( $id ) && $id ) { update_option( 'matin_ai_account_page_created', 1 ); } }
		else { update_option( 'matin_ai_account_page_created', 1 ); }
	}
	public static function styles() : void { if ( ! is_page( 'my-account' ) ) { return; } wp_register_style( 'matin-account', false, [], MATIN_AI_CORE_VERSION ); wp_enqueue_style( 'matin-account' ); wp_add_inline_style( 'matin-account', '.matin-account{max-width:1040px;margin:30px auto;padding:0 18px;direction:rtl;color:var(--matin-text,#172033)}.matin-account-hero{padding:26px;border-radius:22px;background:linear-gradient(125deg,#111827,#293e5b);color:white;margin-bottom:20px}.matin-account-hero h1{color:white}.matin-account-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:18px}.matin-account-nav,.matin-account-panel{border:1px solid #dce3ec;border-radius:18px;padding:18px;background:#ffffffd9;backdrop-filter:blur(14px)}.matin-account-nav a{display:block;padding:11px;border-radius:10px;text-decoration:none}.matin-account-nav a:hover{background:#eef3f9}.matin-ticket{border:1px solid #dce3ec;border-radius:15px;padding:16px;margin:12px 0;background:#fff}.matin-ticket-row{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.matin-status{display:inline-block;padding:5px 9px;border-radius:20px;background:#eef2f7;font-size:12px}.matin-status-confirmed{background:#dcfce7;color:#166534}.matin-status-rejected,.matin-status-cancelled{background:#fee2e2;color:#991b1b}.matin-account input{max-width:100%;padding:10px;border:1px solid #ccd5e1;border-radius:9px}.matin-account button{padding:10px 14px;border-radius:10px;border:1px solid #cdd6e2;cursor:pointer}@media(max-width:680px){.matin-account-layout{grid-template-columns:1fr}.matin-account-nav{display:flex;gap:5px;overflow:auto}.matin-account-nav a{white-space:nowrap}}' ); }
	private static function status_label( string $status ) : string { $labels = [ 'pending' => 'در انتظار تأیید کافه', 'confirmed' => 'تأییدشده', 'rejected' => 'ردشده', 'cancelled' => 'لغوشده' ]; return $labels[ $status ] ?? 'در حال بررسی'; }
	public static function render() : string {
		$message = '';
		if ( isset( $_POST['matin_account_action'] ) ) {
			$action = sanitize_key( wp_unslash( $_POST['matin_account_action'] ) );
			if ( ! isset( $_POST['matin_account_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['matin_account_nonce'] ) ), 'matin_account_action' ) ) { $message = '<p role="alert">درخواست منقضی شده است؛ صفحه را تازه‌سازی کنید.</p>'; }
			elseif ( 'register' === $action && ! is_user_logged_in() ) {
				$name = sanitize_text_field( wp_unslash( $_POST['matin_full_name'] ?? '' ) ); $email = sanitize_email( wp_unslash( $_POST['matin_email'] ?? '' ) ); $phone = sanitize_text_field( wp_unslash( $_POST['matin_phone'] ?? '' ) ); $password = (string) ( $_POST['matin_password'] ?? '' );
				if ( strlen( $name ) < 4 || ! is_email( $email ) || strlen( preg_replace( '/\D/', '', $phone ) ) < 8 || strlen( $password ) < 10 || ! is_email( $email ) || email_exists( $email ) ) { $message = '<p role="alert">نام کامل، ایمیل معتبر، شماره موبایل و رمز عبور حداقل ۱۰ کاراکتری وارد کنید. ایمیل نباید قبلاً ثبت شده باشد.</p>'; }
				else { $username = sanitize_user( current( explode( '@', $email ) ), true ); if ( username_exists( $username ) ) { $username .= wp_generate_password( 4, false, false ); } $user_id = wp_create_user( $username, $password, $email ); if ( is_wp_error( $user_id ) ) { $message = '<p role="alert">ساخت حساب انجام نشد. دوباره تلاش کنید.</p>'; } else { wp_update_user( [ 'ID' => $user_id, 'display_name' => $name, 'first_name' => $name ] ); update_user_meta( $user_id, 'matin_phone', $phone ); wp_set_current_user( $user_id ); wp_set_auth_cookie( $user_id, true, is_ssl() ); wp_safe_redirect( remove_query_arg( 'matin_tab' ) ); exit; } }
			} elseif ( 'settings' === $action && is_user_logged_in() ) {
				$name = sanitize_text_field( wp_unslash( $_POST['matin_full_name'] ?? '' ) ); $phone = sanitize_text_field( wp_unslash( $_POST['matin_phone'] ?? '' ) );
				if ( strlen( $name ) < 4 || strlen( preg_replace( '/\D/', '', $phone ) ) < 8 ) { $message = '<p role="alert">نام و شماره موبایل معتبر وارد کنید.</p>'; }
				else { wp_update_user( [ 'ID' => get_current_user_id(), 'display_name' => $name, 'first_name' => $name ] ); update_user_meta( get_current_user_id(), 'matin_phone', $phone ); $message = '<p role="status">اطلاعات حساب به‌روزرسانی شد.</p>'; }
			}
		}
		if ( ! is_user_logged_in() ) {
			ob_start(); ?>
			<div class="matin-account"><div class="matin-account-hero"><h1>حساب کاربری Matin AI</h1><p>برای نگهداری بلیت‌ها و مدیریت رزروها حساب بسازید یا وارد شوید.</p></div><?php echo wp_kses_post( $message ); ?><div class="matin-account-layout"><section class="matin-account-panel"><h2>ساخت حساب با ایمیل</h2><form method="post"><?php wp_nonce_field( 'matin_account_action', 'matin_account_nonce' ); ?><input type="hidden" name="matin_account_action" value="register"><p><label>نام و نام خانوادگی<br><input name="matin_full_name" autocomplete="name" required minlength="4"></label></p><p><label>ایمیل<br><input type="email" name="matin_email" autocomplete="email" required></label></p><p><label>شماره موبایل<br><input name="matin_phone" autocomplete="tel" inputmode="tel" required minlength="8"></label></p><p><label>رمز عبور (حداقل ۱۰ کاراکتر)<br><input type="password" name="matin_password" autocomplete="new-password" required minlength="10"></label></p><button type="submit">ساخت حساب</button></form></section><section class="matin-account-panel"><h2>قبلاً حساب ساخته‌اید؟</h2><?php wp_login_form( [ 'redirect' => get_permalink(), 'remember' => true, 'form_id' => 'matin-loginform', 'label_username' => 'ایمیل یا نام کاربری', 'label_password' => 'رمز عبور', 'label_remember' => 'مرا به خاطر بسپار', 'label_log_in' => 'ورود به حساب' ] ); ?><p class="matin-account-hint">ورود با Google و Apple نیازمند اتصال OAuth معتبر است؛ دکمه غیرفعال و نمایشی نشان داده نمی‌شود تا اتصال واقعاً پیکربندی شود.</p></section></div></div>
			<?php return (string) ob_get_clean();
		}
		$user = wp_get_current_user(); $tab = sanitize_key( $_GET['matin_tab'] ?? 'tickets' ); if ( ! in_array( $tab, [ 'tickets', 'settings' ], true ) ) { $tab = 'tickets'; }
		$html = '<div class="matin-account"><div class="matin-account-hero"><h1>سلام، ' . esc_html( $user->display_name ?: $user->user_login ) . '</h1><p>رزروها، بلیت‌ها و اطلاعات حساب شما در یک جا.</p></div>' . wp_kses_post( $message ) . '<div class="matin-account-layout"><nav class="matin-account-nav"><a href="' . esc_url( add_query_arg( 'matin_tab', 'tickets' ) ) . '">🎟 بلیت‌های من</a><a href="' . esc_url( add_query_arg( 'matin_tab', 'settings' ) ) . '">⚙ تنظیمات حساب</a><a href="' . esc_url( wp_logout_url( home_url( '/' ) ) ) . '">خروج</a></nav><section class="matin-account-panel">';
		if ( 'settings' === $tab ) { $html .= '<h2>تنظیمات حساب</h2><form method="post">' . wp_nonce_field( 'matin_account_action', 'matin_account_nonce', true, false ) . '<input type="hidden" name="matin_account_action" value="settings"><p><label>نام و نام خانوادگی<br><input name="matin_full_name" value="' . esc_attr( $user->display_name ) . '" required minlength="4"></label></p><p><label>ایمیل (برای تغییر نیازمند تأیید است)<br><input value="' . esc_attr( $user->user_email ) . '" disabled></label></p><p><label>شماره موبایل<br><input name="matin_phone" value="' . esc_attr( (string) get_user_meta( $user->ID, 'matin_phone', true ) ) . '" required minlength="8"></label></p><button type="submit">ذخیره اطلاعات</button></form>'; }
		else { $ids = get_posts( [ 'post_type' => 'matin_reservation', 'post_status' => 'private', 'numberposts' => 100, 'fields' => 'ids', 'meta_query' => [ [ 'key' => '_matin_user_id', 'value' => $user->ID, 'compare' => '=' ] ], 'orderby' => 'date', 'order' => 'DESC' ] ); $html .= '<h2>بلیت‌های من</h2>'; if ( ! $ids ) { $html .= '<p>هنوز رزروی به حساب شما متصل نشده است. برای مشاهده بلیت‌ها باید هنگام رزرو وارد حساب شده باشید.</p>'; } foreach ( $ids as $id ) { $event_id = (int) get_post_meta( $id, '_matin_event_id', true ); $event_title = get_the_title( $event_id ); $status = (string) get_post_meta( $id, '_matin_status', true ); $code = (string) get_post_meta( $id, '_matin_ticket_code', true ); $cafe_id = (int) get_post_meta( $event_id, '_matin_cafe_id', true ); $html .= '<article class="matin-ticket"><div class="matin-ticket-row"><strong>' . esc_html( $event_title ?: 'رزرو Matin AI' ) . '</strong><span class="matin-status matin-status-' . esc_attr( $status ) . '">' . esc_html( self::status_label( $status ) ) . '</span></div><p>کافه: ' . esc_html( get_the_title( $cafe_id ) ?: '—' ) . '</p><p>کد بلیت: <strong>' . esc_html( $code ?: '—' ) . '</strong> · تعداد نفرات: ' . esc_html( (string) get_post_meta( $id, '_matin_guests', true ) ) . '</p><p>زمان برنامه: ' . esc_html( (string) get_post_meta( $event_id, '_matin_starts_at', true ) ) . '</p></article>'; } }
		return $html . '</section></div></div>';
	}}
